"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["36788"],{61449(e){e.exports=JSON.parse('{"id":"V4-040","slug":"globalization","term":"Globalization","also_known_as":[],"difficulty":"Beginner","definition":"Globalization is the growing interconnection of countries\u2019 economies, societies and cultures through trade, investment, movement of people, flows of information and technology.","explanation":["Globalization has accelerated over recent decades because of lower transport and communication costs, the reduction of trade barriers, the spread of the internet and the integration of large economies, such as China and India, into world markets.","Its economic effects include more international trade, global supply chains in which products are made in several countries, increased foreign investment and the spread of technology. For example, a smartphone may be designed in one country, use components from many others and be assembled in yet another.","Supporters argue globalization has lowered prices for consumers, raised productivity and helped lift hundreds of millions of people out of poverty, particularly in Asia. Critics point to job losses in some industries and regions, pressure on wages, environmental damage, the spread of financial crises and the power of multinational companies.","Since around 2008, and especially after the COVID-19 pandemic and rising geopolitical tensions, some commentators have described a slowdown or partial reversal of globalization, as countries focus on resilience, reshoring production and protecting strategic industries."],"note":"","total":1725,"prev":{"slug":"global-macro-strategy","term":"Global Macro Strategy"},"next":{"slug":"go-to-market-strategy","term":"Go-to-Market Strategy"}}')}}]);